package com.fincore.fincore.transaction; import java.math.BigDecimal; import java.time.Instant; public record TransactionResponse(Long id,Long accountId,BigDecimal amount,String category,String description,TransactionType type,Instant occurredAt){static TransactionResponse from(FinanceTransaction t){return new TransactionResponse(t.getId(),t.getAccount().getId(),t.getAmount(),t.getCategory(),t.getDescription(),t.getTransactionType(),t.getOccurredAt());}}
